Implement reverse-mode automatic differentiation in C++. Return ONLY the
struct, no main, no includes, no explanation. You may use <cmath> and <vector>.

    struct Tape {
        int constant(double v);   // a value with no gradient
        int input(double v);      // a value you will want the gradient of
        int add(int a, int b);    // returns the id of the new node
        int mul(int a, int b);
        int sin_(int a);
        int exp_(int a);
        double value(int node) const;
        void backward(int root);  // seed d(root)/d(root) = 1 and sweep back
        double grad(int node) const;
    };

Each call records a node and returns its integer id. `backward(root)` computes
the derivative of `root` with respect to every node.

Requirements:
- Gradients are checked against finite differences to 1e-5.
- A node used more than once must ACCUMULATE gradient from every path that uses
  it: for g = x*x + x, dg/dx is 2x + 1, not 2x and not 1.
- The reverse sweep must visit nodes in an order where every consumer is
  processed before its inputs; recording order makes this easy.
- Constants take part in the forward value but need no gradient.

```cpp
#include <vector>
#include <cmath>

struct Tape {
    struct Node {
        double value;
        double grad = 0.0;
        bool is_input = false;
        char op = 0;
        int arg1 = -1, arg2 = -1;
    };

    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, false, 0, -1, -1});
        return nodes.size() - 1;
    }

    int input(double v) {
        nodes.push_back({v, 0.0, true, 0, -1, -1});
        return nodes.size() - 1;
    }

    int add(int a, int b) {
        double val = nodes[a].value + nodes[b].value;
        nodes.push_back({val, 0.0, false, '+', a, b});
        return nodes.size() - 1;
    }

    int mul(int a, int b) {
        double val = nodes[a].value * nodes[b].value;
        nodes.push_back({val, 0.0, false, '*', a, b});
        return nodes.size() - 1;
    }

    int sin_(int a) {
        double val = std::sin(nodes[a].value);
        nodes.push_back({val, 0.0, false, 's', a, -1});
        return nodes.size() - 1;
    }

    int exp_(int a) {
        double val = std::exp(nodes[a].value);
        nodes.push_back({val, 0.0, false, 'e', a, -1});
        return nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].value;
    }

    void backward(int root) {
        nodes[root].grad = 1.0;
        for (int i = nodes.size() - 1; i >= 0; --i) {
            Node& n = nodes[i];
            if (n.op == '+') {
                nodes[n.arg1].grad += n.grad;
                nodes[n.arg2].grad += n.grad;
            } else if (n.op == '*') {
                nodes[n.arg1].grad += nodes[n.arg2].value * n.grad;
                nodes[n.arg2].grad += nodes[n.arg1].value * n.grad;
            } else if (n.op == 's') {
                nodes[n.arg1].grad += std::cos(nodes[n.arg1].value) * n.grad;
            } else if (n.op == 'e') {
                nodes[n.arg1].grad += nodes[n.arg1].value * n.grad;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};
```
